import json

pairs = {'(': ')', '[': ']', '{': '}', '<': '>'}
closers = set(pairs.values())

given = "< < >"
tokens = given.split()

stack = []
valid = True
for tok in tokens:
    if tok in pairs:
        stack.append(tok)
    elif tok in closers:
        if stack and pairs[stack[-1]] == tok:
            stack.pop()
        else:
            valid = False
            break
    else:
        valid = False
        break

if not valid:
    result = {
        "final_answer": "UNSUPPORTED",
        "evidence": {"input": given, "reason": "input prefix is not reducible to a valid bracket prefix"},
    }
else:
    completion = [pairs[t] for t in reversed(stack)]
    full = tokens + completion
    result = {
        "final_answer": " ".join(completion),
        "evidence": {
            "input": given,
            "unmatched_open_after_input": stack,
            "completion_tokens": completion,
            "full_sequence": " ".join(full),
        },
    }

print(json.dumps(result, separators=(",", ":")))
